import {useFeatureAppEnv} from '@smart/feature-app';
import {Button, Link} from '@smart/react-components';
import {DynamicMediaPicture} from '@smart/web-components';
import classnames from 'classnames';
import React, {useMemo} from 'react';
import {useProductSearch} from '../../../feature-app/contexts/product-search-context';
import {
  EventName,
  createNavigationEvent,
  useTracking,
} from '../../hooks/use-tracking';
import {createLinkProps} from '../../utils/create-link-props';
import styles from './banner.module.scss';

const baseClass = `banner-wrapper`;

interface BannerProps {
  template: 'offer' | 'campaign';
  position?: number;
  title?: string;
  fromLabel?: string;
  price?: string;
  leasingCycleLabel?: string;
  imageUrl?: string;
  description?: string;
  linkLabel?: string;
  linkDestination?: any;
  backgroundColorOption?:
    | 'premium #1'
    | 'premium #3'
    | 'brabus'
    | 'pulse'
    | 'pro+'
    | 'pro,pure+,pure';
  leasingPriceReference: string;
}

const Banner = ({
  template = `offer`,
  title,
  fromLabel,
  price,
  leasingCycleLabel,
  description,
  linkLabel,
  linkDestination,
  imageUrl,
  backgroundColorOption,
  leasingPriceReference,
}: BannerProps) => {
  const track = useTracking();
  const getBackgroundColor = useMemo(() => {
    const colorMapping = {
      'premium #1': `#BCC9C4`,
      'premium #3': `#AAC1CD`,
      'brabus': `#3A3C3F`,
      'pulse': `#799DC9`,
      'pro+': `#DED774`,
      'pro,pure+,pure': `#E4E8EB`,
    };

    if (!backgroundColorOption || !colorMapping[backgroundColorOption]) {
      return `#BCC9C4`;
    }

    return colorMapping[backgroundColorOption];
  }, [backgroundColorOption]);

  const LinkComponent = () => {
    const {
      featureServices: {'s2:history': historyService},
    } = useFeatureAppEnv();
    const {applyFilter} = useProductSearch();

    const handleClick = () => {
      track.event(
        createNavigationEvent({
          url: window.location.href,
          product: [],
          name: (linkLabel || EventName.LEARN_MORE) as EventName,
          destinationUrl: linkDestination?._path,
        }),
      );
    };

    if (linkDestination && linkLabel) {
      const linkProps = createLinkProps({
        destination: linkDestination,
        historyService,
        applyFilter,
      });

      return (
        <Button asChild variant="secondary" onClick={handleClick} mode={200}>
          <Link className={styles.link} href={linkProps.href}>
            {linkLabel}
          </Link>
        </Button>
      );
    }
    return null;
  };
  return (
    <div className={styles[baseClass]}>
      <div
        className={classnames(styles[`${baseClass}__image-wrapper`], {
          [styles[`${baseClass}__offer-template`] as string]:
            !!backgroundColorOption,
        })}
        style={{
          backgroundColor: getBackgroundColor,
        }}
      >
        <DynamicMediaPicture
          className={classnames({
            [styles[`campaign__picture`] as string]: !backgroundColorOption,
          })}
          imageUrl={imageUrl || ``}
          imageConfigs={[
            {
              aspectRatio: `1-1`,
              sizes: `100vw`,
            },
          ]}
          imageAltText={``}
          hasImageTransparency={!!backgroundColorOption}
          initialIsInView
          noLoadingLogo
          isObjectFit
          fetchPriority="high"
        />
      </div>
      <div className={styles[`${baseClass}__content-wrapper`]}>
        {template === `offer` ? (
          <>
            <div className={styles[`from-label`]}>{fromLabel}</div>
            <div className={styles[`price-wrapper`]}>
              <div className={styles[`price`]}>{price}</div>
              <div className={styles[`leasing-cycle`]}>
                {leasingCycleLabel}
                <sup>{leasingPriceReference}</sup>
              </div>
            </div>
          </>
        ) : (
          <div className={styles.title}>{title}</div>

import type {ApiProps, StackContext} from 'sst/constructs';
import {Api, use} from 'sst/constructs';
import {AppConfig} from './AppConfig';

type Routes = Record<
  string,
  {
    function: {
      handler: string;
      timeout?: number;
      memorySize?: number;
      functionName?: string;
    };
  }
>;
const getBffName = (path: string) => path.split(`/`).pop();
const getBffMethod = (path: string) => path.split(` `)[0];
const enrichRoutes = (
  routes: Routes,
  target: string,
  stage: string,
): ApiProps['routes'] => {
  if (routes) {
    return Object.entries(routes).reduce<ApiProps['routes']>(
      (
        acc,
        [
          path,
          {
            [`function`]: {handler, timeout, memorySize},
          },
        ],
      ) => {
        if (acc)
          acc[path] = {
            function: {
              handler,
              ...(timeout && {timeout}),
              ...(memorySize && {memorySize}),
              functionName: `BFF-${target.toUpperCase()}-${getBffMethod(
                path,
              )}-${getBffName(path)}-${stage}`,
              description: `${getBffName(path)} ${target} => ${
                path.split(` `)[1]
              }`,
            },
          };
        return acc;
      },
      {},
    );
  }
  return routes;
};

export function BffApi({stack}: StackContext) {
  const {hostedZone, target, featureAppName} = use(AppConfig);
  const baseUrl = `/__app__/${featureAppName}/${target}`;
  const routes: Routes = {
    [`GET ${baseUrl}/bff/app-model`]: {
      function: {
        handler: `src/bff/app-model/index.handler`,
        functionName: `${featureAppName}-${target}-app-model`,
      },
    },
    [`GET ${baseUrl}/bff/product-search-model`]: {
      function: {
        handler: `src/bff/product-search-model/index.handler`,
        functionName: `${featureAppName}-${target}-product-search-model`,
      },
    },
  };

  const api = new Api(stack, `api`, {
    customDomain: {
      hostedZone,
      domainName: [`stage`, `dev`, `prod`].includes(stack.stage)
        ? `bff.${hostedZone}`
        : `bff.${stack.stage}.${hostedZone}`,
    },
    routes: enrichRoutes(routes, target, stack.stage),
  });

  stack.addOutputs({
    apiUrl: api.customDomainUrl ?? api.url,
  });

  return api;
}

